import{_ as t,o as i,c as h,a2 as c}from"./chunks/framework.62rcL0wY.js";const u=JSON.parse('{"title":"Nguồn tài liệu và ghi công","description":"","frontmatter":{},"headers":[],"relativePath":"phu-luc/nguon.md","filePath":"phu-luc/nguon.md"}'),a={name:"phu-luc/nguon.md"};function r(g,n,e,d,o,l){return i(),h("div",null,[...n[0]||(n[0]=[c('<h1 id="nguon-tai-lieu-va-ghi-cong" tabindex="-1">Nguồn tài liệu và ghi công <a class="header-anchor" href="#nguon-tai-lieu-va-ghi-cong" aria-label="Permalink to &quot;Nguồn tài liệu và ghi công&quot;">​</a></h1><p>Trang này nêu rõ các nguồn tư liệu gốc được sử dụng để biên soạn bộ tài liệu Clickermann v4.13 tiếng Việt, bảng đối chiếu mục lục với tệp trợ giúp gốc và nguyên tắc phát hành miễn phí cho cộng đồng.</p><h2 id="nguon-tu-lieu-goc" tabindex="-1">Nguồn tư liệu gốc <a class="header-anchor" href="#nguon-tu-lieu-goc" aria-label="Permalink to &quot;Nguồn tư liệu gốc&quot;">​</a></h2><p>Bộ tài liệu hướng dẫn Clickermann v4.13 bằng tiếng Việt này được biên soạn dựa trên các nguồn sau:</p><ol><li><strong>Nguồn chính thức:</strong> Tệp hướng dẫn đi kèm chương trình <strong><code>help.chm</code></strong> của <strong>Clickermann v4.13.014</strong> (cập nhật ngày 24.04.2018 / 16.05.2018), do tác giả <strong>J.Challenger</strong> biên soạn bằng tiếng Nga. <ul><li>Trang chủ chính thức của Clickermann: <a href="http://crapware.aidf.org" target="_blank" rel="noreferrer">http://crapware.aidf.org</a></li><li>Diễn đàn chính thức: <a href="http://crapware.aidf.org/forum/" target="_blank" rel="noreferrer">http://crapware.aidf.org/forum/</a></li><li>Nhóm cộng đồng VK chính thức: <a href="http://vk.com/clickermann" target="_blank" rel="noreferrer">http://vk.com/clickermann</a></li></ul></li><li><strong>Nguồn tham khảo đối chiếu:</strong> Sách hướng dẫn cộng đồng <em><strong>The Basic Clickermann Guidebook</strong></em> (2nd Edition, 160 trang) của tác giả <strong>Chô tô</strong>, được chia sẻ công khai cho cộng đồng người Việt tham khảo. <ul><li>Liên kết blog cá nhân của tác giả Chô tô (ghi ở trang 160 của sách): <a href="https://chotodeptrai.blogspot.com/" target="_blank" rel="noreferrer">https://chotodeptrai.blogspot.com/</a></li><li>Bộ tài liệu này không sao chép câu chữ hay ví dụ của sách mà dịch trực tiếp từ <code>help.chm</code> gốc của tác giả J.Challenger, đồng thời đối chiếu với sách của Chô tô để ghi chú rõ những điểm khác biệt hoặc chưa thống nhất tại trang <a href="/clickermann-guide-vi/phu-luc/can-kiem-tra-tren-windows.html">Cần kiểm tra trên Windows</a>.</li></ul></li><li><strong>Thư viện cộng đồng <code>alt_winmode.cms</code> (<code>alternative windowed mode v1.1</code>):</strong><ul><li>Được chia sẻ công khai trên diễn đàn chính thức của Clickermann (<a href="http://crapware.aidf.org/forum/" target="_blank" rel="noreferrer">http://crapware.aidf.org/forum/</a>), hiện chưa rõ tên tác giả cụ thể (bộ tài liệu sẵn sàng mở đường liên hệ để bổ sung thông tin ghi công ngay khi xác nhận được tác giả của thư viện). Xem chi tiết tại trang <a href="/clickermann-guide-vi/nang-cao/alt-winmode.html">Thư viện alt_winmode</a>.</li></ul></li><li><strong>Kỹ thuật thực chiến từ script thực tế của người biên soạn:</strong><ul><li>Các mẫu kỹ thuật tại trang <a href="/clickermann-guide-vi/cam-nang/thuc-chien.html">Thực chiến: kỹ thuật viết script</a> được rút ra từ script thực tế do chính người biên soạn bộ tài liệu này tự viết và sử dụng; bản script gốc không công bố nguyên bản mà được viết lại toàn bộ ví dụ minh họa trên Notepad và Paint.</li></ul></li><li><strong>Bảng mã phím và script dò mã phím của Mai Bảo Long:</strong><ul><li>Bảng mã phím đo được cho <code>KEYDOWN</code>/<code>KEYUP</code> (xem mục <a href="/clickermann-guide-vi/phu-luc/ma-phim.html#khi-keydown-can-ma-khac">Khi <code>KEYDOWN</code> cần mã khác</a>) và mẫu script <a href="/clickermann-guide-vi/cam-nang/thuc-chien.html#do-ma-phim">Dò mã phím</a> được tác giả <strong>Mai Bảo Long</strong> tự dò và chia sẻ công khai tại bài viết <a href="https://maibaolongne.blogspot.com/2024/09/tai-lieu-clickermann-by-mai-bao-long.html" target="_blank" rel="noreferrer">Tài liệu Clickermann by Mai Bảo Long</a>.</li><li>Lưu ý: bài viết gốc trên blog không ghi rõ điều kiện đo (đo trên ứng dụng nào và ở chế độ chạy nào của Clickermann), nên toàn bộ nội dung đối chiếu liên quan được gắn nhãn <code>🟠 Chưa thống nhất</code> để chờ kiểm chứng thực tế trên máy Windows.</li></ul></li></ol><h2 id="bang-doi-chieu-muc-luc-voi-tep-help-chm-goc" tabindex="-1">Bảng đối chiếu mục lục với tệp <code>help.chm</code> gốc <a class="header-anchor" href="#bang-doi-chieu-muc-luc-voi-tep-help-chm-goc" aria-label="Permalink to &quot;Bảng đối chiếu mục lục với tệp `help.chm` gốc&quot;">​</a></h2><p>Bảng dưới đây liệt kê toàn bộ các mục trong cây mục lục của tệp <code>help.chm</code> (v4.13.014) theo đúng thứ tự gốc (đã dịch tên mục sang tiếng Việt) cùng tên gọi và trang tương ứng trong bộ tài liệu này:</p><table tabindex="0"><thead><tr><th>Thứ tự trong mục lục <code>help.chm</code> (dịch sang tiếng Việt)</th><th>Tên gọi khi trích dẫn trong tài liệu</th><th>Trang tương ứng trong bộ tài liệu</th></tr></thead><tbody><tr><td><strong>Clickermann</strong> → Clickermann là gì</td><td>phần Tổng quan / Giới thiệu chung</td><td><a href="/clickermann-guide-vi/">Tổng quan Clickermann</a>, <a href="/clickermann-guide-vi/bat-dau/script-dau-tien.html">Viết script đầu tiên</a></td></tr><tr><td><strong>Giao diện</strong> → Cửa sổ chính</td><td>bài Màn hình chính</td><td><a href="/clickermann-guide-vi/bat-dau/man-hinh-chinh.html">Màn hình chính</a></td></tr><tr><td><strong>Giao diện</strong> → Trình soạn thảo</td><td>bài Trình soạn thảo</td><td><a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo và kính lúp</a></td></tr><tr><td><strong>Giao diện</strong> → Quản lý cửa sổ</td><td>bài Quản lý cửa sổ</td><td><a href="/clickermann-guide-vi/bat-dau/quan-ly-cua-so.html">Quản lý cửa sổ</a></td></tr><tr><td><strong>Tính năng đặc biệt</strong> → Khóa cửa sổ</td><td>bài Khóa cửa sổ</td><td><a href="/clickermann-guide-vi/khai-niem/khoa-cua-so.html">Chế độ khóa cửa sổ</a></td></tr><tr><td><strong>Tính năng đặc biệt</strong> → Giảm màu</td><td>bài Giảm màu</td><td><a href="/clickermann-guide-vi/khai-niem/mau-sac.html">Màu sắc và giảm màu (<code>COLORMODE</code>)</a></td></tr><tr><td><strong>Tính năng đặc biệt</strong> → Chế độ PS/2</td><td><em>(tài liệu không hướng dẫn)</em></td><td><em>(chỉ ghi nhận tên chỉ thị ở <a href="/clickermann-guide-vi/khai-niem/ngon-ngu.html">Ngôn ngữ script</a>)</em></td></tr><tr><td><strong>Tính năng đặc biệt</strong> → Gọi DLL</td><td>bài Plugin</td><td><a href="/clickermann-guide-vi/khai-niem/plugin.html">Plugin mở rộng (DLL)</a></td></tr><tr><td><strong>Câu hỏi thường gặp (FAQ)</strong></td><td>phần FAQ</td><td><a href="/clickermann-guide-vi/xu-ly-loi.html">Xử lý lỗi và câu hỏi thường gặp (FAQ)</a></td></tr><tr><td><strong>Lịch sử phát triển</strong></td><td>Lịch sử phiên bản</td><td><a href="/clickermann-guide-vi/phu-luc/lich-su.html">Lịch sử phát triển phiên bản</a></td></tr><tr><td><strong>Thông tin khác</strong> (Về chương trình)</td><td>phần Thông tin chương trình</td><td><a href="/clickermann-guide-vi/bat-dau/cai-dat.html">Cài đặt và chạy lần đầu</a>, <a href="/clickermann-guide-vi/phu-luc/nguon.html">Nguồn tài liệu</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Giới thiệu ngôn ngữ</td><td>phần Giới thiệu ngôn ngữ</td><td><a href="/clickermann-guide-vi/khai-niem/ngon-ngu.html">Ngôn ngữ script</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Làm việc với số</td><td>mục Làm việc với số</td><td><a href="/clickermann-guide-vi/lenh/so.html">Số, biến và mảng</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Chuỗi và tệp</td><td>mục Chuỗi và tệp</td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html">Chuỗi, tệp tin, bộ nhớ tạm và HTTP</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Chuột</td><td>mục Chuột</td><td><a href="/clickermann-guide-vi/lenh/chuot.html">Chuột</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Bàn phím</td><td>mục Bàn phím</td><td><a href="/clickermann-guide-vi/lenh/ban-phim.html">Bàn phím</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Cấu trúc chính</td><td>mục Cấu trúc lệnh</td><td><a href="/clickermann-guide-vi/lenh/cau-truc.html">Điều kiện, vòng lặp, chương trình con</a>, <a href="/clickermann-guide-vi/khai-niem/luong.html">Luồng (<code>THREAD</code>)</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Phân tích màn hình</td><td>mục Màn hình</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html">Màn hình và màu sắc</a>, <a href="/clickermann-guide-vi/khai-niem/bo-dem-anh.html">Bộ đệm ảnh</a>, <a href="/clickermann-guide-vi/khai-niem/toa-do.html">Hệ tọa độ</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Xuất thông tin</td><td>mục Xuất thông tin</td><td><a href="/clickermann-guide-vi/lenh/nhat-ky.html">Nhật ký và âm báo</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Script và plugin</td><td>mục Script và plugin</td><td><a href="/clickermann-guide-vi/lenh/kich-ban.html">Điều khiển script và hệ thống</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → WinAPI và khóa cửa sổ</td><td>mục WinAPI và khóa cửa sổ</td><td><a href="/clickermann-guide-vi/lenh/winapi.html">Cửa sổ và WinAPI</a></td></tr><tr><td><strong>Ngôn ngữ kịch bản</strong> → Phụ lục 1: Mã phím</td><td>phần Mã phím</td><td><a href="/clickermann-guide-vi/phu-luc/ma-phim.html">Bảng mã phím và hằng số</a></td></tr></tbody></table><h2 id="tinh-chat-tai-lieu-cong-dong" tabindex="-1">Tính chất tài liệu cộng đồng <a class="header-anchor" href="#tinh-chat-tai-lieu-cong-dong" aria-label="Permalink to &quot;Tính chất tài liệu cộng đồng&quot;">​</a></h2><ul><li>Đây là <strong>tài liệu cộng đồng</strong>, không phải tài liệu chính thức của tác giả Clickermann.</li><li>Tài liệu được biên soạn và chia sẻ hoàn toàn <strong>miễn phí, không bán</strong> dưới mọi hình thức.</li><li>Bản thân phần mềm Clickermann cũng là phần mềm miễn phí (<strong>FREEWARE</strong>) của tác giả J.Challenger — nghiêm cấm mọi hành vi đóng gói bán lại chương trình hoặc bất kỳ phần nào của chương trình.</li></ul>',10)])])}const s=t(a,[["render",r]]);export{u as __pageData,s as default};
